-- Same schema is installed idempotently by src.config.database.initialize.
CREATE TABLE IF NOT EXISTS datasets (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS models (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id VARCHAR(80) PRIMARY KEY,natural_key VARCHAR(180) UNIQUE NOT NULL,payload LONGTEXT NOT NULL);
